      "reason": "The autoescape extension was removed and built in, so the documented import path jinja2.ext.autoescape does not exist in jinja2.ext.",
      "code_citation": {
        "path": "docs/extensions.rst",
        "start_line": 243,
        "end_line": 246,
        "quote": ".. versionchanged:: 2.9\n\n    This extension was removed and is now built-in. Enabling the\n    extension no longer does anything."
      },
      "suggested_doc_fix": "Remove the '**Import name:** ``jinja2.ext.autoescape``' line, or replace it with a note that no import is needed because the feature is built in."
    }
  ],
  "additional_findings": [
    {
      "finding_id": "AD-1",
      "drift_kind": "signature",
      "explanation": "The new-style gettext documentation refers to env.install_translations, but the environment method documented elsewhere is install_gettext_translations.",
      "doc_citation": {
        "path": "docs/extensions.rst",
        "start_line": 156,
        "end_line": 158,
        "quote": "You can use \"new style\" gettext calls by setting\n``env.newstyle_gettext = True`` or passing ``newstyle=True`` to\n``env.install_translations``. They are fully supported by the Babel"
      },
      "code_citation": {
        "path": "docs/extensions.rst",
        "start_line": 53,
        "end_line": 53,
        "quote": ".. method:: jinja2.Environment.install_gettext_translations(translations, newstyle=False)"
      },
      "proposed_fix": "Change ``env.install_translations`` to ``env.install_gettext_translations``."
    }
  ]
}
